mapper.select:
SELECT 
  FROM posts p
  JOIN users u ON u.id = p.user_id
 WHERE p.board  = #{board}
   AND p.status = 'PUBLISHED'

 LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE posts
   SET title = #{title}, content = #{content}
 WHERE id = #{postId}

UPDATE posts
   SET status = #{status}
 WHERE id = #{postId}
   AND status = 'PUBLISHED'
